const navLinks=document.querySelectorAll(".nav-dock a"),sections=document.querySelectorAll("section");let scrollTimeout;window.addEventListener("scroll",()=>{scrollTimeout&&cancelAnimationFrame(scrollTimeout),scrollTimeout=requestAnimationFrame(()=>{let e="about";sections.forEach(t=>{const c=t.offsetTop;if(window.scrollY>=c-150){const o=t.getAttribute("id");o&&o!=="hero"&&(e=o)}}),window.innerHeight+window.scrollY>=document.body.offsetHeight-50&&(e="contact"),navLinks.forEach(t=>{t.classList.remove("active"),t.getAttribute("href")===`#${e}`&&t.classList.add("active")})})});
